CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
ALTER TABLE public.enquiries ADD COLUMN follow_up_at timestamptz, ADD COLUMN internal_notes text NOT NULL DEFAULT '';
GRANT SELECT, UPDATE ON public.enquiries TO authenticated;
CREATE POLICY admin_enquiry_read ON public.enquiries FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_enquiry_update ON public.enquiries FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.enquiry_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enquiry_id uuid NOT NULL REFERENCES public.enquiries(id), actor_id uuid, created_at timestamptz NOT NULL DEFAULT now(), old_status text NOT NULL, new_status text NOT NULL, change_summary text NOT NULL);
GRANT SELECT ON public.enquiry_history TO authenticated;
GRANT ALL ON public.enquiry_history TO service_role;
ALTER TABLE public.enquiry_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_history_read ON public.enquiry_history FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_enquiry_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.enquiry_history(enquiry_id,actor_id,old_status,new_status,change_summary) VALUES(NEW.id,auth.uid(),OLD.status,NEW.status,'Enquiry details, status, notes or follow-up updated'); RETURN NEW; END $$;
CREATE TRIGGER enquiry_update_history AFTER UPDATE ON public.enquiries FOR EACH ROW EXECUTE FUNCTION public.audit_enquiry_update();